/* ===== MSSQL – Verificar Backups Recientes (usp_VerificarBackupsRecientes) ===== */
SET NOCOUNT ON;
USE sqldb_database_maintenance;
EXEC dbo.usp_VerificarBackupsRecientes;

parameters.jsCode:
// ===== Function – Decidir estado (Backups) =====
// Entrada: MERGE de SP (BaseDeDatos, TipoBackup, FechaUltimoBackup, Estado) + last_state
// Estados de entrada (columna Estado): 'ATRASADO', 'SIN BACKUP', 'OK'
// Regla: ATRASADO | SIN BACKUP -> ALARM ; OK -> NORMAL
// Emite fields: base_datos, tipo_backup, fecha_ultimo_utc, horas_desde, state, transition, ...

const P = $node["Set - Params"].json || {};
const norm = s => String(s ?? "").trim();
const toIso = v => (v ? new Date(v).toISOString() : null);

const allIn = $input.all().map(i => i.json);

const currentRows = [];
const lastRows = [];
for (const r of allIn) {
  const hasSP = (r.BaseDeDatos!=null || r.base_datos!=null) && (r.TipoBackup!=null || r.tipo_backup!=null || r.Estado!=null || r.estado!=null || r.FechaUltimoBackup!=null || r.fecha_ultimo!=null);
  const hasState = (r.base_datos!=null && (r.last_state!=null || r.last_change_utc!=null) && r.instance_id!=null);
  if (hasSP && !hasState) currentRows.push(r);
  else if (hasState && !hasSP) lastRows.push(r);
}

const lastMap = {};
for (const r of lastRows) {
  const base = norm(r.base_datos);
  lastMap[base] = { state: String(r.last_state||"").toUpperCase() || "UNKNOWN", last_change_utc: r.last_change_utc || null };
}

const nowIso = new Date().toISOString();
const out = [];
const seen = new Set();

const hoursSince = (iso) => {
  if (!iso) return null;
  const ms = (new Date(nowIso) - new Date(iso));
  return Math.max(0, Math.round(ms / 3600000)); // horas
};

for (const r of currentRows) {
  const base = norm(r.BaseDeDatos ?? r.base_datos ?? "N/D");
  const tipo = norm(r.TipoBackup ?? r.tipo_backup ?? "FULL");
  const fechaIso = toIso(r.FechaUltimoBackup ?? r.fecha_ultimo);
  const estadoIn = String(r.Estado ?? r.estado ?? "OK").toUpperCase();

  const stNow = (estadoIn === "OK") ? "NORMAL" : "ALARM";
  const prev = lastMap[base]?.state || "UNKNOWN";

  let transition = "NONE";
  if (prev !== "ALARM" && stNow === "ALARM") transition = "RAISE";
  else if (prev === "ALARM" && stNow === "NORMAL") transition = "RECOVER";
  else if (prev === "ALARM" && stNow === "ALARM") transition = "HOLD";

  const alarm_started_at = (transition === "RECOVER") ? (lastMap[base]?.last_change_utc || null) : null;
  const alarm_duration_min = (transition === "RECOVER" && alarm_started_at)
    ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000))
    : null;

  out.push({ json: {
    instance_name: P.instance_name || "N/D",
    base_datos: base,
    tipo_backup: tipo,
    fecha_ultimo_utc: fechaIso,
    horas_desde: hoursSince(fechaIso),
    estado_in: estadoIn,       // OK | ATRASADO | SIN BACKUP
    state: stNow,              // NORMAL | ALARM
    transition,
    alarm_started_at,
    alarm_duration_min,
    ts_utc: nowIso,
    last_change: nowIso
  }});
  seen.add(base);
}

// RECOVERY para DB que estaban en ALARM y ya no vinieron (desapareció de resultados)
for (const [base, info] of Object.entries(lastMap)) {
  if (info.state !== "ALARM") continue;
  if (seen.has(base)) continue;

  const alarm_started_at = info.last_change_utc || null;
  const alarm_duration_min = alarm_started_at ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000)) : null;

  out.push({ json: {
    instance_name: P.instance_name || "N/D",
    base_datos: base,
    tipo_backup: "FULL",
    fecha_ultimo_utc: null,
    horas_desde: null,
    estado_in: "OK",
    state: "NORMAL",
    transition: "RECOVER",
    alarm_started_at,
    alarm_duration_min,
    ts_utc: nowIso,
    last_change: nowIso
  }});
}

return out;

function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (ALERTA – Backups) ===
const P  = $node["Set - Params"].json || {};
const tz = Number(P.tz_offset_hours || 0); // ya no lo usamos para la fecha del SP
const inItems = $items().map(i => i.json);
if (!inItems.length) return [];

// Formatea sin convertir zona horaria (solo normaliza string)
const fmtDate = (v) => {
  if (!v) return "N/D";
  // Si viene como Date
  if (v instanceof Date && !isNaN(v)) {
    const iso = v.toISOString().replace("T", " ").substring(0, 19);
    return iso;
  }
  const s = String(v).trim();
  // SQL style: "2025-12-30 12:00:20.000" -> quitamos milisegundos
  if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}(\.\d+)?$/.test(s)) {
    return s.replace("T"," ").substring(0,19);
  }
  // ISO -> lo dejamos legible sin convertir
  if (s.includes("T")) return s.replace("T"," ").replace("Z","").substring(0,19);
  return s;
};

// Hora “local” para el header (aquí sí puedes usar offset fijo)
const nowLocal = () => {
  const base = Date.now();
  const off  = tz * 3600 * 1000;
  return new Date(base + off).toISOString().replace("T"," ").substring(0,19);
};

// orden: SIN BACKUP primero, luego ATRASADO por mayor horas_desde
const rows = inItems.map(r => ({
  base: r.base_datos ?? r.BaseDeDatos,
  tipo: r.tipo_backup ?? r.TipoBackup,
  // IMPORTANTE: usar la columna real del SP
  fecha: fmtDate(r.FechaUltimoBackup ?? r.fecha_ultimo_backup ?? r.fecha_ultimo_utc),
  horas: (Number.isFinite(r.horas_desde) ? `${r.horas_desde}` : (r.Horas ?? "N/D")),
  estado: r.estado_in ?? r.Estado
})).sort((a,b) => {
  const rank = s => s==="SIN BACKUP" ? 2 : (s==="ATRASADO" ? 1 : 0);
  const rr = rank(b.estado) - rank(a.estado);
  if (rr!==0) return rr;
  const ha = isNaN(+a.horas) ? -1 : +a.horas;
  const hb = isNaN(+b.horas) ? -1 : +b.horas;
  return hb - ha;
});

const limit = Number(P.rows_limit_alert || 20);
const limited = rows.slice(0, limit);

const inst = P.instance_name || "N/D";
const total = rows.length;
const shown = limited.length;

// Resumen por estado
const counts = limited.reduce((acc, r) => {
  acc[r.estado] = (acc[r.estado] || 0) + 1;
  return acc;
}, {});
const countsText = Object.entries(counts)
  .sort((a,b) => b[1]-a[1])
  .map(([k,v]) => `${k}: ${v}`)
  .join(" | ");

// 1 línea por registro
const detailLines = limited.map(r => {
  const fecha = r.fecha || "N/D";
  const horas = (r.horas === "N/D" || r.horas === null || r.horas === undefined) ? "N/D" : r.horas;
  return `• **${r.base}** | ${r.tipo} | ${fecha} | ${horas}h | **${r.estado}**`;
});

const detailText =
  detailLines.join("  \n") +
  `  \n  \nMostrando ${shown} de ${total}.`;

const body = [
  { type:"Container", bleed:true, items:[
    { type:"TextBlock", text:`🔴 **ALERTA – Backups • ${inst}**`, size:"Large", weight:"Bolder", wrap:true },
    { type:"TextBlock", text:`🗂️ **Bases con problema:** ${rows.length}`, wrap:true },
    { type:"TextBlock", text:`🕒 **Hora (local):** ${nowLocal()}`, wrap:true }
  ]},
  { type:"TextBlock", text:" ", spacing:"Small" },

  { type:"Container", style:"emphasis", bleed:true, items:[
    { type:"TextBlock", text:"📊 **Detalle**", weight:"Bolder", wrap:true, spacing:"Small" },
    ...(countsText ? [{ type:"TextBlock", text:`**Resumen:** ${countsText}`, wrap:true }] : []),
    { type:"TextBlock", text:`**Columnas:** BaseDeDatos | TipoBackup | FechaUltimoBackup | Horas | Estado`, wrap:true },
    { type:"TextBlock", text: detailText, wrap:true }
  ]},

  { type:"TextBlock", text:" ", spacing:"Medium" },
  { type:"TextBlock", text:"⚠️ **Causas probables**", weight:"Bolder", wrap:true },
  { type:"TextBlock", text:(P.causes_backup||[]).map(x=>`• ${x}`).join("  \n"), wrap:true },

  { type:"TextBlock", text:" ", spacing:"Small" },
  { type:"TextBlock", text:"🛠️ **Recomendaciones**", weight:"Bolder", wrap:true },
  { type:"TextBlock", text:(P.reco_backup||[]).map(x=>`• ${x}`).join("  \n"), wrap:true }
];

return [{ json: {
  type: "message",
  attachments: [{
    contentType: "application/vnd.microsoft.card.adaptive",
    content: {
      $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
      type:"AdaptiveCard",
      version:"1.4",
      msteams:{ width:"Full" },
      body
    }
  }]
}}];

// === Function – RECOVERY (Backups) ===
return $input.all().map(it => {
  const j = it.json;
  const send_recovery = (String(j.state).toUpperCase()==='NORMAL' && String(j.transition).toUpperCase()==='RECOVER');
  return { json: { ...j, send_recovery } };
});

function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

