  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (RECOVERY – Backups) ===
const P  = $node["Set - Params"].json || {};
const tz = Number(P.tz_offset_hours || 0);
const items = $items().map(i => i.json);
if (!items.length) return [];

const toLocal = iso => {
  const base = iso ? new Date(iso).getTime() : Date.now();
  const off  = tz * 3600 * 1000;
  return new Date(base + off).toISOString().replace("T"," ").substring(0,19);
};

const rows = items.map(r => ({
  base: r.base_datos,
  tipo: r.tipo_backup || "FULL",
  fecha: r.fecha_ultimo_utc ? toLocal(r.fecha_ultimo_utc) : "N/D",
  dur: (Number.isFinite(r.alarm_duration_min) ? `${r.alarm_duration_min} min` : "N/D")
}));

const header = {
  type: "ColumnSet", bleed: true,
  columns: [
    { type:"Column", width: 3, items:[{ type:"TextBlock", text:"BaseDeDatos", weight:"Bolder", wrap:true }]},
    { type:"Column", width: 1, items:[{ type:"TextBlock", text:"Tipo", weight:"Bolder", wrap:true }]},
    { type:"Column", width: 2, items:[{ type:"TextBlock", text:"Fecha último (local)", weight:"Bolder", wrap:true }]},
    { type:"Column", width: 2, items:[{ type:"TextBlock", text:"Duración alarma", weight:"Bolder", wrap:true }]}
  ],
  spacing: "None"
};
const row = r => ({
  type: "ColumnSet", bleed:true,
  columns: [
    { type:"Column", width: 3, items:[{ type:"TextBlock", text:String(r.base), wrap:true }]},
    { type:"Column", width: 1, items:[{ type:"TextBlock", text:String(r.tipo), wrap:true }]},
    { type:"Column", width: 2, items:[{ type:"TextBlock", text:String(r.fecha), wrap:true }]},
    { type:"Column", width: 2, items:[{ type:"TextBlock", text:String(r.dur), wrap:true }]}
  ],
  spacing: "Small"
});

const inst = P.instance_name || "N/D";

const body = [
  { type:"Container", bleed:true, items:[
    { type:"TextBlock", text:`🟢 **RECUPERADO – Backups • ${inst}**`, size:"Large", weight:"Bolder", wrap:true },
    { type:"TextBlock", text: rows.length === 1 ? `🗂️ **Base recuperada:** ${rows[0].base}` : `🗂️ **Bases recuperadas:** ${rows.length}`, wrap:true }
  ]},
  { type:"TextBlock", text:" ", spacing:"Small" },
  { type:"Container", style:"emphasis", bleed:true, items:[
    { type:"TextBlock", text:"📊 **Detalle**", weight:"Bolder", wrap:true, spacing:"Small" },
    header,
    ...rows.map(row)
  ]},
  { type:"TextBlock", text:" ", spacing:"Medium" },
  { type:"FactSet", facts:[
    ...(items[0]?.alarm_started_at ? [{ title:"Alarma desde (local)", value: toLocal(items[0].alarm_started_at) }] : []),
    ...(Number.isFinite(items[0]?.alarm_duration_min) ? [{ title:"Duración de la alarma", value: `${items[0].alarm_duration_min} min` }] : []),
    { title:"Hora (local)", value: toLocal() }
  ]}
];

return [{ json: {
  type: "message",
  attachments: [{
    contentType: "application/vnd.microsoft.card.adaptive",
    content: { $schema: "http://adaptivecards.io/schemas/adaptive-card.json", type:"AdaptiveCard", version:"1.4", msteams:{width:"Full"}, body }
  }]
}}];

// Construye el T-SQL para registrar detalle + TOPs (OpsObservability)
const P = $node['Set - Params'].json || {};
const items = $items().map(i => i.json);

const esc = (s) => (s == null ? '' : String(s).replace(/'/g, "''"));

let sql = `
SET NOCOUNT ON;
USE OpsObservability;

DECLARE @now_utc DATETIME = SYSUTCDATETIME();
DECLARE @inst_name NVARCHAR(200) = N'${esc(P.instance_name)}';
DECLARE @env NVARCHAR(50) = N'${esc(P.environment)}';
DECLARE @reg NVARCHAR(50) = N'${esc(P.region)}';

-- Asegurar instancia
DECLARE @id INT = (SELECT instance_id FROM dbo.monitoring_instance WHERE instance_name=@inst_name);
IF @id IS NULL
BEGIN
  INSERT INTO dbo.monitoring_instance(instance_name, environment, region)
  VALUES(@inst_name, @env, @reg);
  SET @id = SCOPE_IDENTITY();
END;

-- Crear tabla detalle si no existe
IF OBJECT_ID('dbo.monitoring_backup_status','U') IS NULL
BEGIN
  CREATE TABLE dbo.monitoring_backup_status (
    id INT IDENTITY(1,1) PRIMARY KEY,
    ts_utc        DATETIME NOT NULL DEFAULT (SYSUTCDATETIME()),
    instance_id   INT NOT NULL,
    base_datos    NVARCHAR(200),
    tipo_backup   NVARCHAR(20),
    fecha_ultimo  DATETIME NULL,
    horas_desde   INT NULL,
    estado        NVARCHAR(20),
    run_id        UNIQUEIDENTIFIER NOT NULL
  );
END;
`;

sql += `
DECLARE @rid UNIQUEIDENTIFIER = NEWID();
`;

// Insert detalle
for (const r of items) {
  sql += `
INSERT INTO dbo.monitoring_backup_status
  (ts_utc, instance_id, base_datos, tipo_backup, fecha_ultimo, horas_desde, estado, run_id)
VALUES
  (@now_utc, @id, N'${esc(r.base_datos)}', N'${esc(r.tipo_backup||"FULL")}', ${r.fecha_ultimo_utc ? "CAST(N'"+esc(r.fecha_ultimo_utc)+"' AS datetime)" : "NULL"}, ${Number.isFinite(r.horas_desde)? r.horas_desde : "NULL"}, N'${esc(r.estado_in||"OK")}', @rid);
`;
}

// TOPs por horas_desde (solo si hay en ALARM), si no diag
const alerts = items.filter(r => String(r.state).toUpperCase()==='ALARM').slice().sort((a,b)=> (b.horas_desde||-1) - (a.horas_desde||-1));

if (alerts.length === 0) {
  sql += `
INSERT INTO dbo.monitoring_top_entities
  (ts_utc, instance_id, scope_type, scope_key, metric_name, metric_value, rank_n, run_id)
VALUES
  (@now_utc, @id, 'backup_status', 'diag:NO_ALERTS', 'no_data', 0, 0, @rid);
`;
} else {
  let rank = 1;
  for (const r of alerts) {
    const key = `${esc(r.base_datos)}`;
    const metric = Number.isFinite(r.horas_desde) ? r.horas_desde : 999999;
    sql += `
INSERT INTO dbo.monitoring_top_entities
  (ts_utc, instance_id, scope_type, scope_key, metric_name, metric_value, rank_n, run_id)
VALUES
  (@now_utc, @id, 'backup_status', N'${key}', 'hours_since', ${metric}, ${rank}, @rid);
`;
    rank += 1;
  }
}

sql += `
SELECT 'ok' AS message, @now_utc AS ts_utc, @id AS instance_id, @rid AS run_id;
`;

return [{ json: { sql } }];

