SET NOCOUNT ON;
DECLARE @now_utc DATETIME = GETUTCDATE();

DECLARE @inst sysname       = N'{{$json.instance_name}}';
DECLARE @base nvarchar(128) = N'{{$json.base_datos}}';
DECLARE @state varchar(10)  = N'{{$json.state}}';

DECLARE @instance_id int;
SELECT TOP 1 @instance_id = instance_id
FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
WHERE instance_name=@inst;

IF @instance_id IS NULL
BEGIN
  INSERT INTO OpsObservability.dbo.monitoring_instance(instance_name)
  VALUES(@inst);
  SELECT TOP 1 @instance_id = instance_id
  FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
  WHERE instance_name=@inst;
END

IF OBJECT_ID('OpsObservability.dbo.monitoring_backup_state','U') IS NULL
BEGIN
  CREATE TABLE OpsObservability.dbo.monitoring_backup_state(
    instance_id INT NOT NULL,
    base_datos NVARCHAR(200) NOT NULL,
    last_state NVARCHAR(10) NOT NULL,
    last_change_utc DATETIME NOT NULL,
    CONSTRAINT PK_backup_state PRIMARY KEY(instance_id, base_datos)
  );
END

;MERGE OpsObservability.dbo.monitoring_backup_state AS T
USING (SELECT @instance_id AS instance_id, @base AS base_datos) AS S
ON (T.instance_id = S.instance_id AND T.base_datos = S.base_datos)
WHEN MATCHED THEN
  UPDATE SET last_state=@state, last_change_utc=@now_utc
WHEN NOT MATCHED THEN
  INSERT(instance_id, base_datos, last_state, last_change_utc)
  VALUES(@instance_id, @base, @state, @now_utc);

/* ================================================================
 Validación Monitoreo Backups – OpsObservability (sin GO)
 Incluye:
   0) Existencia de tablas
   1) Últimos 50 registros crudos (detalle)
   2) Resumen por run_id
   3) Conteo estados 24h
   4) Verificación TOPs (último run)
================================================================ */
USE OpsObservability;
SET NOCOUNT ON;

PRINT '>>> 0) Verificando tablas requeridas...';
IF OBJECT_ID('dbo.monitoring_backup_status','U') IS NULL
  RAISERROR('Falta dbo.monitoring_backup_status', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_backup_status';
IF OBJECT_ID('dbo.monitoring_instance','U') IS NULL
  RAISERROR('Falta dbo.monitoring_instance', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_instance';
IF OBJECT_ID('dbo.monitoring_top_entities','U') IS NULL
  RAISERROR('Falta dbo.monitoring_top_entities', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_top_entities';
PRINT '---';

PRINT '>>> 1) Últimos 50 registros crudos';
SELECT TOP (50)
  ts_utc, instance_id, base_datos, tipo_backup, fecha_ultimo, horas_desde, estado, run_id
FROM dbo.monitoring_backup_status WITH (NOLOCK)
ORDER BY ts_utc DESC;
PRINT '---';

PRINT '>>> 2) Resumen por run_id (20 últimos)';
WITH last_runs AS (
  SELECT TOP (20) run_id, MAX(ts_utc) ts_ult
  FROM dbo.monitoring_backup_status WITH (NOLOCK)
  GROUP BY run_id
  ORDER BY ts_ult DESC
)
SELECT r.ts_ult, m.instance_name, d.run_id,
       COUNT(*) AS filas_total,
       SUM(CASE WHEN d.estado IN ('ATRASADO','SIN BACKUP') THEN 1 ELSE 0 END) AS filas_alerta,
       SUM(CASE WHEN d.estado = 'OK' THEN 1 ELSE 0 END) AS filas_ok
FROM last_runs r
JOIN dbo.monitoring_backup_status d WITH (NOLOCK) ON d.run_id = r.run_id
