USING (SELECT @instance_id AS instance_id, @base AS base_datos) AS S
ON (T.instance_id = S.instance_id AND T.base_datos = S.base_datos)
WHEN MATCHED THEN
  UPDATE SET last_state=@state, last_change_utc=@now_utc
