   2) Resumen por run_id
   3) Conteo estados 24h
   4) Verificación TOPs (último run)
================================================================ */
USE OpsObservability;
SET NOCOUNT ON;

PRINT '>>> 0) Verificando tablas requeridas...';
IF OBJECT_ID('dbo.monitoring_backup_status','U') IS NULL
  RAISERROR('Falta dbo.monitoring_backup_status', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_backup_status';
IF OBJECT_ID('dbo.monitoring_instance','U') IS NULL
  RAISERROR('Falta dbo.monitoring_instance', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_instance';
IF OBJECT_ID('dbo.monitoring_top_entities','U') IS NULL
  RAISERROR('Falta dbo.monitoring_top_entities', 10, 1) WITH NOWAIT; ELSE PRINT 'OK: monitoring_top_entities';
PRINT '---';

PRINT '>>> 1) Últimos 50 registros crudos';
SELECT TOP (50)
  ts_utc, instance_id, base_datos, tipo_backup, fecha_ultimo, horas_desde, estado, run_id
FROM dbo.monitoring_backup_status WITH (NOLOCK)
ORDER BY ts_utc DESC;
PRINT '---';

PRINT '>>> 2) Resumen por run_id (20 últimos)';
WITH last_runs AS (
  SELECT TOP (20) run_id, MAX(ts_utc) ts_ult
  FROM dbo.monitoring_backup_status WITH (NOLOCK)
  GROUP BY run_id
  ORDER BY ts_ult DESC
)
SELECT r.ts_ult, m.instance_name, d.run_id,
       COUNT(*) AS filas_total,
       SUM(CASE WHEN d.estado IN ('ATRASADO','SIN BACKUP') THEN 1 ELSE 0 END) AS filas_alerta,
       SUM(CASE WHEN d.estado = 'OK' THEN 1 ELSE 0 END) AS filas_ok
FROM last_runs r
JOIN dbo.monitoring_backup_status d WITH (NOLOCK) ON d.run_id = r.run_id
JOIN dbo.monitoring_instance m WITH (NOLOCK) ON m.instance_id = d.instance_id
GROUP BY r.ts_ult, m.instance_name, d.run_id
ORDER BY r.ts_ult DESC;
PRINT '---';

PRINT '>>> 3) Conteo estados (24h)';
SELECT m.instance_name,
  SUM(CASE WHEN s.estado IN ('ATRASADO','SIN BACKUP') THEN 1 ELSE 0 END) AS alertas,
  SUM(CASE WHEN s.estado='OK' THEN 1 ELSE 0 END) AS oks,
  MIN(s.ts_utc) AS desde_utc,
  MAX(s.ts_utc) AS hasta_utc
FROM dbo.monitoring_backup_status s WITH (NOLOCK)
JOIN dbo.monitoring_instance m WITH (NOLOCK) ON m.instance_id = s.instance_id
WHERE s.ts_utc >= DATEADD(DAY,-1,SYSUTCDATETIME())
GROUP BY m.instance_name
ORDER BY alertas DESC;
PRINT '---';

PRINT '>>> 4) Verificación de TOPs (último run)';
WITH last_run AS (
  SELECT TOP (1) run_id, MAX(ts_utc) ts_ult
  FROM dbo.monitoring_backup_status WITH (NOLOCK)
  GROUP BY run_id
  ORDER BY ts_ult DESC
)
SELECT t.ts_utc, i.instance_name, t.scope_type, t.scope_key, t.metric_name, t.metric_value, t.rank_n, t.run_id
FROM dbo.monitoring_top_entities t WITH (NOLOCK)
JOIN last_run r ON r.run_id = t.run_id
LEFT JOIN dbo.monitoring_instance i WITH (NOLOCK) ON i.instance_id = t.instance_id
WHERE t.scope_type = 'backup_status'
ORDER BY t.rank_n ASC, t.metric_value DESC;
PRINT '---';
